efine kSignature			'SS17'			// Application signature #define kFileType			'SF17'			// Data file type #define kStationery			'sF17'			// Stationery file type // Bundle Constants// ------------------#define kBundleID						128#define kApplicationID					128#define kDocumentID						129#define kStationeryID					130resource 'MBAR' (kMBarDisplayed,#if qNames"MultiLocale MBAR",#endif	purgeable) {	{ mApple; mFile; mEdit }};include "Defaults.rsrc"	'aete' (0);				// Grab the default AppleEvent terminologyinclude "Defaults.rsrc" 'CMNU' (mApple);		// Grab the default Apple/File menusinclude "Defaults.rsrc" 'CMNU' (mFile);include "Defaults.rsrc" 'CMNU' (mEdit);			// Grab the default Edit menuinclude "Defaults.rsrc"  'vers' (1);			// Application or file specificinclude "Defaults.rsrc"  'vers' (2);			// Overall package#if qNames#define kNamesSizeDelta 75#else#define kNamesSizeDelta 0#endif#if qDebug#define kDebugSizeDelta 0#else#define kDebugSizeDelta 0#endif#define kModelFarSizeDelta 0#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,					reserved,	reserved,	reserved,	reserved,		/* Suggested partition size */	(2000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(1800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// TempoGridView specific resources //--------------------------------------------------------------------------------------------------#ifndef MW_Rez		include "TempoGridView.view" not 'vers';#endifinclude "TempoGridView.rsrc" not 'ckid';include "Defaults.rsrc"  'ALRT' (phAboutApp);resource 'DITL' (phAboutApp,#if qNames"phAboutApp",#endif	purgeable) {	 {	/* array DITLarray: 3 elements */		/* [1] */		{167, 288, 187, 348},		Button {			enabled,			"OK"		};		/* [2] */		{10, 75, 154, 348},		StaticText {			disabled,			"This sample program demonstrates how to implement Mac OS 8 (Tempo) adornments in a grid view."			"\n"			WRITTEN_WITH_MACAPP		};		/* [3] */		{10, 20, 42, 52},		Icon {			disabled,			noteIcon		}	}};//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	kApplicationName};resource 'FREF' (kApplicationID,#if qNames"Application",#endif	purgeable) {	'APPL',	0,	""};resource 'FREF' (kDocumentID,#if qNames"Document",#endif	purgeable) {	kFileType,	1,	""};resource 'FREF' (kStationeryID,#if qNames"Stationery",#endif	purgeable) {	kStationery,	2,	""};resource 'BNDL' (kBundleID,#if qNameskApplicationName,#endif	purgeable) {	kSignature,	0,	{ /* array TypeArray: 2 elements */		/* [1] */		'ICN#',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		},		/* [2] */		'FREF',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		}	}};resource 'open' (kBundleID){	kSignature, { kFileType, kStationery }};resource 'kind' (kBundleID){	kSignature,	verUS,	{		ftApplicationName, 	kApplicationName,		kFileType,			kApplicationName " Document",		kStationery,		kApplicationName " Stationery",	}};//--------------------------------------------------------------------------------------------------// Icons//--------------------------------------------------------------------------------------------------include "Defaults.rsrc"  'ICN#' (kApplicationID);	// MacApp Family large black & white	include "Defaults.rsrc"  'ICN#' (kDocumentID);		// MacApp Document large black & whiteinclude "Defaults.rsrc"  'ICN#' (kStationeryID);	// MacApp Stationery large black & white	include "Defaults.rsrc"  'ics#' (kApplicationID);	// MacApp Family small black & white	include "Defaults.rsrc"  'ics#' (kDocumentID);		// MacApp Document small black & whiteinclude "Defaults.rsrc"  'ics#' (kStationeryID);	// MacApp Stationery small black & whiteinclude "Defaults.rsrc"  'ics4' (kApplicationID);	// MacApp Family small 4 bitinclude "Defaults.rsrc"  'ics4' (kDocumentID);		// MacApp Document small 4 bitinclude "Defaults.rsrc"  'ics4' (kStationeryID);	// MacApp Stationery small 4 bitinclude "Defaults.rsrc"  'ics8' (kApplicationID);	// MacApp Family small 4 bitinclude "Defaults.rsrc"  'ics8' (kDocumentID);		// MacApp Document small 4 bitinclude "Defaults.rsrc"  'ics8' (kStationeryID);	// MacApp Stationery small 4 bitinclude "Defaults.rsrc"  'icl4' (kApplicationID);	// MacApp Family large 4 bitinclude "Defaults.rsrc"  'icl4' (kDocumentID);		// MacApp Document large 4 bitinclude "Defaults.rsrc"  'icl4' (kStationeryID);	// MacApp Stationery large 4 bitinclude "Defaults.rsrc"  'icl8' (kApplicationID);	// MacApp Family large 8 bitinclude "Defaults.rsrc"  'icl8' (kDocumentID);		// MacApp Document large 8 bitinclude "Defaults.rsrc"  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit